  ('alice', true, true, 'Especially dangerous paired with Angela.', array['thick']::text[], 2, 3, 5, 'S tier with Angela, A tier without; in the meta. Sustain teamfighter, front-to-back. Easily kited early; scales hard late. Weak to anti-heal (Baxia), crowd control and kiting heroes (Karrie, Lunox). Strong against tanky EXP fighters and fighter gold laners. Alpha can win early but Alice mostly out-sustains him late. Franco''s suppress is strong before Alice stacks. Lower ranks have a harder time against her.', 'confirmed', 'magic', array['exp', 'jungle']::text[], '{"frontline":4,"cc":4,"mobility":3,"wave_clear":3,"objective":1,"hg_defense":3,"teamfight":5,"pickoff":2,"sustain":5}'::jsonb, 3, true, 'A', 2, array[]::text[], array[]::text[], array['thick']::text[], array['anti_heal', 'cc', 'mobility']::text[], array[]::text[]),
