  ('alucard', false, false, '', array[]::text[], 3, 4, 4, 'Decent against certain drafts: strong sustain and damage against enemies without stuns (lifesteal). Bad against drafts with stunners. If he gets ahead early he snowballs very hard and farms very fast. Weak to anti-heal, hard crowd control and kiting. Much stronger in low ranks and solo queue (uncoordinated teams).', 'confirmed', 'physical', array['jungle']::text[], '{"frontline":2,"cc":0,"mobility":3,"wave_clear":3,"objective":3,"hg_defense":2,"teamfight":2,"pickoff":2,"sustain":5}'::jsonb, 1, true, 'C', 2, array[]::text[], array[]::text[], array[]::text[], array['cc', 'anti_heal']::text[], array[]::text[]),
