  ('akai', false, false, '', array[]::text[], 4, 4, 3, 'Very recommended against certain drafts, e.g. Aulus, Lukas and dive comps — easily disrupts them. Very strong high-ground defense. Not naturally a frontline. Falls off late due to long cooldowns and more mobile enemies. Strong invade: built-in dash + stun at levels 1–2 for pickoffs. Weak to Purify and CC immunity (Diggie). Lesley is the best anti-tank into him; Karrie, X.Borg and Dyrroth get spun by his ultimate.', 'confirmed', 'physical', array['roam', 'jungle']::text[], '{"frontline":2,"cc":5,"mobility":2,"wave_clear":2,"objective":2,"hg_defense":4,"teamfight":4,"pickoff":3,"sustain":2}'::jsonb, 3, true, null, 0, array['Dive']::text[], array[]::text[], array[]::text[], array[]::text[], array[]::text[]),
