  ('argus', false, false, '', array['split', 'thick']::text[], 2, 3, 4, 'Very situational, B tier (A if played right). Good against burst (Kadita, Eudora, Tigreal combos that usually delete a solo target). Stays in long drawn-out teamfights and is a very good split pusher. Generally wins fights against tanks. Weak against kiters that run away (Chang''e, Lesley, Granger, Beatrix); needs the team to back him up, otherwise he split pushes. Team dependent.', 'confirmed', 'physical', array['exp']::text[], '{"frontline":2,"cc":0,"mobility":2,"wave_clear":4,"objective":4,"hg_defense":0,"teamfight":2,"pickoff":2,"sustain":4}'::jsonb, 2, true, 'B', -1, array[]::text[], array[]::text[], array['thick']::text[], array['mobility']::text[], array[]::text[]),
